.section {
  background-color: #fff;
  background-image: url('/images/webflow/hero-background-1.png'), linear-gradient(#019ae614, #019ae600);
  background-position: 50% 100%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: cover, auto;
  padding-top: 4rem;
  padding-bottom: 4rem;
  position: relative;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

.inner {
  text-align: center;
  max-width: 70rem;
  margin-left: auto;
  margin-right: auto;
}

/* Badge */
.badgeRow {
  justify-content: center;
  align-items: center;
  display: flex;
  margin-bottom: 1.5rem;
}

.badge {
  background-color: #21cfff12;
  border: 1px solid #05bafe;
  border-radius: 20px;
  padding: 0 13px;
  line-height: 32px;
  display: inline-flex;
  align-items: center;
}

.badgeText {
  margin: 0;
  font-size: 12px;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-weight: 500;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Heading */
.heading {
  color: #092245;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 50px;
  font-weight: 700;
  line-height: 1.2;
  margin-top: 0;
  margin-bottom: 1rem;
  text-decoration: none;
}

/* Subtitle */
.subtitle {
  color: #2b2b2b;
  max-width: 52rem;
  margin-left: auto;
  margin-right: auto;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin-bottom: 0;
}

/* Stat badges grid */
.badgeGrid {
  grid-column-gap: 14px;
  grid-row-gap: 14px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  grid-auto-columns: 1fr;
  max-width: 840px;
  margin: 2rem auto 0;
  display: grid;
}

.statBadge {
  background-color: #fff;
  border-radius: 10px;
  align-items: center;
  padding: 13px 16px;
  display: flex;
  gap: 10px;
  box-shadow: 0 0 5px #0000001a;
}

.statBadgeText {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.3;
  margin: 0;
  text-align: left;
}

/* Video embed */
.videoWrap {
  border-radius: 10px;
  width: 100%;
  max-width: 800px;
  margin: 48px auto 40px;
  box-shadow: 0 0 5px #0000001a;
  overflow: hidden;
}

.videoContainer {
  position: relative;
  height: 0;
  width: 100%;
  overflow: hidden;
  padding-bottom: calc(56.25% + 32px);
  border-radius: 10px;
}

/* CTA buttons */
.ctaRow {
  justify-content: center;
  align-items: center;
  margin-top: 1.5rem;
  display: flex;
  gap: 1.25rem;
  flex-wrap: wrap;
}

.btnPrimary {
  color: #fff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1rem;
  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  box-shadow: 0 0 5px #0000001a;
  transition: background-color 0.2s;
}

.btnPrimary:hover {
  background-color: #092245;
  background-image: url('/images/webflow/Group-46729-2.svg');
  background-repeat: no-repeat;
  background-size: auto;
}

.btnSecondary {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1rem;
  background-color: #21cfff21;
  background-image: url('/images/webflow/Group-46729-1.svg');
  background-position: 94%;
  background-repeat: no-repeat;
  background-size: auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  box-shadow: 0 0 5px #0000001a;
  transition: all 0.2s;
}

.btnSecondary:hover {
  color: #fff;
  background-color: #092245;
}

/* Gradient fade at bottom */
.gradientFade {
  background-image: linear-gradient(#fff0, #fff);
  height: 120px;
  position: absolute;
  inset: auto 0 0;
  pointer-events: none;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .btnPrimary {
    background-image: url('/images/webflow/Group-46729.svg'), linear-gradient(90deg, #21cfff, #019ae6);
    background-position: 93%, 0 0;
    background-repeat: no-repeat, repeat;
    background-size: auto, auto;
  }

  .btnPrimary:hover {
    background-image: url('/images/webflow/Group-46729-2.svg');
  }
}

