@media screen and (max-width: 991px) {
  .badgeGrid {
    grid-template-columns: 1fr 1fr;
    max-width: 540px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .heading {
    font-size: 36px;
  }

  .badgeGrid {
    grid-template-columns: 1fr 1fr;
    max-width: 100%;
  }
}

