/* Number circle */
.numberCircle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid #21cfff60;
  background-color: #fff;
  margin-bottom: 20px;
}

.number {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 1;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.stepTitle {
  color: #092245;
  font-family: 'Roobert PRO', Arial, sans-serif;
